<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{Message}from'@arco-design/web-vue';import{adminApi,type AuditLogRow}from'@/api/admin';import{PublicApiError}from'@/api/client';import{formatDate,optionalPositiveInt,safeJSON}from'@/utils/format'
const rows=ref<AuditLogRow[]>([]),detail=ref<AuditLogRow|null>(null),loading=ref(false),detailLoading=ref(false),hasMore=ref(false),next=ref(0);const filters=reactive({service:'',eventType:'',userId:'',status:'',requestId:'',from:'',to:''});function report(e:unknown){Message.error(e instanceof PublicApiError?e.message:'请求失败')}
function time(value:string){return value?new Date(value).toISOString():undefined};async function load(append=false){loading.value=true;try{const page=await adminApi.logs({beforeId:append?next.value:undefined,limit:50,service:filters.service,eventType:filters.eventType,userId:optionalPositiveInt(filters.userId),status:filters.status,requestId:filters.requestId,from:time(filters.from),to:time(filters.to)});rows.value=append?[...rows.value,...page.list]:page.list;hasMore.value=page.hasMore;next.value=page.nextBeforeId}catch(e){report(e)}finally{loading.value=false}};async function show(row:AuditLogRow){detailLoading.value=true;try{detail.value=await adminApi.log(row.id)}catch(e){report(e)}finally{detailLoading.value=false}};onMounted(()=>load())
</script>
<template><section class="page-stack"><a-card :bordered="false"><div class="toolbar log-toolbar"><div><h2>结构化审计日志</h2><p>按事件、服务、用户、请求链路和时间过滤；详情始终以文本节点渲染，不解释 HTML。</p></div><a-space wrap><a-input v-model="filters.service" placeholder="service"/><a-input v-model="filters.eventType" placeholder="event type"/><a-input v-model="filters.userId" placeholder="user ID"/><a-select v-model="filters.status" allow-clear placeholder="status" style="width:130px"><a-option value="success">success</a-option><a-option value="failed">failed</a-option><a-option value="denied">denied</a-option></a-select><a-input v-model="filters.requestId" placeholder="request ID"/><input v-model="filters.from" class="native-datetime" type="datetime-local"/><input v-model="filters.to" class="native-datetime" type="datetime-local"/><a-button type="primary" @click="load()">查询</a-button></a-space></div></a-card><a-card :bordered="false"><a-table row-key="id" :data="rows" :loading="loading" :pagination="false" :scroll="{x:1200}"><template #columns><a-table-column title="事件" :width="230"><template #cell="{record}"><strong>{{record.eventType}}</strong><div class="muted">{{record.service}} · {{record.action}}</div></template></a-table-column><a-table-column title="状态" :width="100"><template #cell="{record}"><a-tag :color="record.status==='success'?'green':record.status==='denied'?'orange':'red'">{{record.status}}</a-tag></template></a-table-column><a-table-column title="用户/资源" :width="180"><template #cell="{record}">用户 {{record.userId??'-'}}<br/>{{record.resourceType||'-'}} {{record.resourceId||''}}</template></a-table-column><a-table-column title="Request ID" :width="230"><template #cell="{record}"><span class="mono">{{record.requestId||'-'}}</span></template></a-table-column><a-table-column title="时间" :width="180"><template #cell="{record}">{{formatDate(record.occurredAt)}}</template></a-table-column><a-table-column title="操作" :width="90" fixed="right"><template #cell="{record}"><a-button size="small" :loading="detailLoading" @click="show(record)">详情</a-button></template></a-table-column></template></a-table><div class="load-more"><a-button v-if="hasMore" @click="load(true)">加载更多</a-button></div></a-card><a-modal :visible="detail!==null" title="审计事件详情" :footer="false" width="720px" @cancel="detail=null"><a-descriptions v-if="detail" :column="2" bordered><a-descriptions-item label="Event ID">{{detail.eventId}}</a-descriptions-item><a-descriptions-item label="Schema">{{detail.schemaVersion}}</a-descriptions-item><a-descriptions-item label="Request ID">{{detail.requestId||'-'}}</a-descriptions-item><a-descriptions-item label="Path">{{detail.method}} {{detail.path}}</a-descriptions-item></a-descriptions><h4>安全 Metadata</h4><pre class="safe-json">{{safeJSON(detail?.metadata)}}</pre></a-modal></section></template>
